package main

import (
	"fmt"
	"image"
	"image/color"
	"image/png"
	"log"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"sync"
)

type PipelineConfig struct {
	OutputDir    string
	LogFormat    string
	Watermark    string
	MaxWidth     int
	MaxHeight    int
	DebugEnabled bool
}

type ProcessingJob struct {
	SourcePath string
	OutputName string
	Metadata   map[string]string
}

var (
	config     *PipelineConfig
	configOnce sync.Once
	jobQueue   = make(chan ProcessingJob, 100)
)

func loadConfig() *PipelineConfig {
	configOnce.Do(func() {
		config = &PipelineConfig{
			OutputDir:    getEnvOrDefault("IMG_OUTPUT_DIR", "/tmp/processed"),
			LogFormat:    getEnvOrDefault("IMG_LOG_FORMAT", "[%s] %s: %s"),
			Watermark:    getEnvOrDefault("IMG_WATERMARK", "(c) Company"),
			MaxWidth:     1920,
			MaxHeight:    1080,
			DebugEnabled: os.Getenv("IMG_DEBUG") == "1",
		}
	})
	return config
}

func getEnvOrDefault(key, defaultVal string) string {
	if val := os.Getenv(key); val != "" {
		return val
	}
	return defaultVal
}

func sanitizeFilename(name string) string {
	name = filepath.Base(name)
	name = strings.ReplaceAll(name, "..", "")
	name = strings.Map(func(r rune) rune {
		if r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9' || r == '.' || r == '-' || r == '_' {
			return r
		}
		return '_'
	}, name)
	return name
}

func logPipelineEvent(stage string, job ProcessingJob, message string) {
	cfg := loadConfig()
	timestamp := "2024-01-15T10:30:00Z"

	if cfg.DebugEnabled {
		details := buildDebugDetails(job)
		formatted := fmt.Sprintf(cfg.LogFormat, timestamp, stage, message)
		fmt.Fprintf(os.Stderr, formatted+" details: "+details+"\n")
	} else {
		formatted := fmt.Sprintf(cfg.LogFormat, timestamp, stage, message)
		fmt.Fprintf(os.Stderr, formatted+"\n")
	}
}

func buildDebugDetails(job ProcessingJob) string {
	var parts []string
	for k, v := range job.Metadata {
		parts = append(parts, k+"="+v)
	}
	return strings.Join(parts, ", ")
}

func resizeImage(src image.Image, maxW, maxH int) image.Image {
	bounds := src.Bounds()
	w, h := bounds.Dx(), bounds.Dy()

	if w <= maxW && h <= maxH {
		return src
	}

	ratio := float64(w) / float64(h)
	newW, newH := maxW, int(float64(maxW)/ratio)
	if newH > maxH {
		newH = maxH
		newW = int(float64(maxH) * ratio)
	}

	dst := image.NewRGBA(image.Rect(0, 0, newW, newH))
	for y := 0; y < newH; y++ {
		for x := 0; x < newW; x++ {
			srcX := x * w / newW
			srcY := y * h / newH
			dst.Set(x, y, src.At(srcX+bounds.Min.X, srcY+bounds.Min.Y))
		}
	}
	return dst
}

func applyWatermark(img *image.RGBA, text string) {
	bounds := img.Bounds()
	startX := bounds.Max.X - len(text)*7 - 10
	startY := bounds.Max.Y - 20

	for i, ch := range text {
		_ = ch
		for dy := 0; dy < 12; dy++ {
			for dx := 0; dx < 6; dx++ {
				px := startX + i*7 + dx
				py := startY + dy
				if px >= bounds.Min.X && px < bounds.Max.X && py >= bounds.Min.Y && py < bounds.Max.Y {
					img.Set(px, py, color.RGBA{255, 255, 255, 128})
				}
			}
		}
	}
}

func processImage(job ProcessingJob) error {
	cfg := loadConfig()

	logPipelineEvent("decode", job, "starting image decode")

	f, err := os.Open(job.SourcePath)
	if err != nil {
		return fmt.Errorf("open source: %w", err)
	}
	defer f.Close()

	src, _, err := image.Decode(f)
	if err != nil {
		return fmt.Errorf("decode image: %w", err)
	}

	logPipelineEvent("resize", job, "resizing image")
	resized := resizeImage(src, cfg.MaxWidth, cfg.MaxHeight)

	rgba, ok := resized.(*image.RGBA)
	if !ok {
		bounds := resized.Bounds()
		rgba = image.NewRGBA(bounds)
		for y := bounds.Min.Y; y < bounds.Max.Y; y++ {
			for x := bounds.Min.X; x < bounds.Max.X; x++ {
				rgba.Set(x, y, resized.At(x, y))
			}
		}
	}

	logPipelineEvent("watermark", job, "applying watermark")
	applyWatermark(rgba, cfg.Watermark)

	outPath := filepath.Join(cfg.OutputDir, sanitizeFilename(job.OutputName))
	outFile, err := os.Create(outPath)
	if err != nil {
		return fmt.Errorf("create output: %w", err)
	}
	defer outFile.Close()

	if err := png.Encode(outFile, rgba); err != nil {
		return fmt.Errorf("encode png: %w", err)
	}

	logPipelineEvent("complete", job, "saved to "+outPath)
	return nil
}

func handleUpload(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	if err := r.ParseMultipartForm(10 << 20); err != nil {
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}

	file, header, err := r.FormFile("image")
	if err != nil {
		http.Error(w, "missing image", http.StatusBadRequest)
		return
	}
	defer file.Close()

	tmpPath := filepath.Join(os.TempDir(), "upload_"+sanitizeFilename(header.Filename))
	tmp, err := os.Create(tmpPath)
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}

	buf := make([]byte, 4096)
	for {
		n, readErr := file.Read(buf)
		if n > 0 {
			tmp.Write(buf[:n])
		}
		if readErr != nil {
			break
		}
	}
	tmp.Close()

	job := ProcessingJob{
		SourcePath: tmpPath,
		OutputName: sanitizeFilename(header.Filename),
		Metadata: map[string]string{
			"original_name": header.Filename,
			"content_type":  r.Header.Get("Content-Type"),
			"client_ip":     r.RemoteAddr,
		},
	}

	if err := processImage(job); err != nil {
		logPipelineEvent("error", job, err.Error())
		http.Error(w, "processing failed", http.StatusInternalServerError)
		return
	}

	os.Remove(tmpPath)
	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "processed: %s", job.OutputName)
}

func main() {
	cfg := loadConfig()
	os.MkdirAll(cfg.OutputDir, 0750)

	http.HandleFunc("/upload", handleUpload)
	log.Printf("Starting image pipeline server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
